                bne.s   loc_8375A                       ; If no signpost is active, branch
                btst    #0,$38(a1)
                beq.s   loc_8375A                       ; If signpost hasn't landed, branch
                lea     word_8379E(pc),a2
                move.w  x_pos(a0),d0
                move.w  x_pos(a1),d1
                add.w   (a2)+,d0
                cmp.w   d0,d1
                blo.s   loc_8374C
                add.w   (a2)+,d0
                cmp.w   d0,d1
                bhs.s   loc_8374C
                move.w  y_pos(a0),d0
                move.w  y_pos(a1),d1
                add.w   (a2)+,d0
                cmp.w   d0,d1
                blo.s   loc_8374C
                add.w   (a2)+,d0
                cmp.w   d0,d1
                blo.s   loc_83760

loc_8374C:
                moveq   #signextendB(sfx_GroundSlide),d0  ; If signpost has landed
                jsr     (Play_SFX).l
                move.l  #Sprite_OnScreen_Test,(a0)

loc_8375A:
                jmp     (Delete_Sprite_If_Not_In_Range).l
; ---------------------------------------------------------------------------

loc_83760:
                bclr    #0,$38(a1)                      ; If signpost has landed and is in range
                move.l  #Obj_Monitor,(a0)               ; make this object a monitor
                move.b  #2,routine(a0)
                move.b  #4,$3C(a0)
                move.w  #-$500,y_vel(a0)
                moveq   #signextendB(sfx_BubbleAttack),d0
                jsr     (Play_SFX).l
                bclr    #0,render_flags(a0)
                beq.s   loc_83798
                bset    #7,art_tile(a0)
                clr.b   status(a0)

loc_83798:
                jmp     (Sprite_OnScreen_Test).l
